package com.littlemakers.village.nativeapp;

import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.media.MediaPlayer;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;

/** Bundled MP4 playback with child-controlled play, branching questions, captions and no network. */
public final class CinemaActivity extends Activity {
 CinematicState state;VideoView video;ImageView poster;
 boolean ready,failed,renderedFirstFrame,active,pendingStart;
 int clipCompletions;private int token;private long resetGeneration;private ThemeManager theme;
 private GameDatabase db;private PlayerWallet wallet;private SoundEngine sound;private OfflineNarrator narrator;
 private LinearLayout root,body,choices;private TextView caption,status;private Button play;
 private final Handler handler=new Handler(Looper.getMainLooper());
 private final Runnable tick=new Runnable(){public void run(){if(!active||video==null)return;if(ready&&!failed&&video.isPlaying()){int sec=video.getCurrentPosition()/1000;status.setText("Playing · "+sec+" / "+Math.max(1,video.getDuration()/1000)+" sec");}handler.postDelayed(this,500);}};
 private int dp(int n){return theme.dp(n);}
 private android.content.SharedPreferences prefs(){return getSharedPreferences("cinema",0);}
 @Override public void onCreate(Bundle b){super.onCreate(b);theme=new ThemeManager(this);db=GameDatabase.create(this);wallet=new PlayerWallet(db);sound=new SoundEngine(this);narrator=new OfflineNarrator(this,()->{if(status!=null)status.setText("No offline English voice is installed. The caption stays on screen.");});resetGeneration=getSharedPreferences("family",0).getLong("quest_reset_generation",0);if(b!=null&&b.getBoolean("in_film")){state=CinematicState.restore(b.getString("film_state",""));openScene(false);}else library();if(Build.VERSION.SDK_INT>=33)Back.register(this);}
 static final class Back{static void register(CinemaActivity a){a.getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,a::back);}}
 private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextColor(theme.text);t.setTextSize(size);t.setTypeface(theme.font(size>=20));t.setPadding(dp(4),dp(6),dp(4),dp(6));return t;}
 private Button button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setContentDescription(label);b.setMinHeight(dp(64));b.setPadding(dp(12),dp(8),dp(12),dp(8));GameUi.control(b,theme);b.setOnClickListener(v->{sound.tap();v.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);action.run();});return b;}
 private void add(View view){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(dp(4),dp(5),dp(4),dp(5));body.addView(view,p);}
 private void stopVideo(){token++;handler.removeCallbacks(tick);pendingStart=false;if(video!=null){video.setOnPreparedListener(null);video.setOnCompletionListener(null);video.setOnErrorListener(null);video.stopPlayback();video=null;}ready=false;}
 private void base(String title){stopVideo();theme=new ThemeManager(this);root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(theme.background);setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});root.requestApplyInsets();getWindow().getDecorView().setSystemUiVisibility(theme.dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.addView(button("‹",this::back),new LinearLayout.LayoutParams(dp(64),dp(64)));TextView heading=text(title,22);heading.setGravity(Gravity.CENTER);bar.addView(heading,new LinearLayout.LayoutParams(0,-2,1));Button home=button("⌂",this::finish);home.setContentDescription("Close cinema and return to the calling screen");bar.addView(home,new LinearLayout.LayoutParams(dp(64),dp(64)));root.addView(bar);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(12),dp(4),dp(12),dp(18));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}
 void library(){persist();state=null;base("Discovery cinema");add(text("You guide the film",24));add(text("Watch a short scene. Choose a path. Make a discovery.",17));ImageView cover=new ImageView(this);cover.setImageResource(R.drawable.moon_arrival);cover.setScaleType(ImageView.ScaleType.FIT_CENTER);cover.setContentDescription("The Moon, seen in a lunar-data visualization");add(cover);Button start=button("Explore the Moon",()->startStory(false));GameUi.primary(start,theme);add(start);if(!prefs().getString("moon-0","").isEmpty())add(button("Continue my expedition",()->startStory(true)));add(text("1 branching film · 4 distinct clips · 2 discovery paths",15));add(text("Offline MP4 video. Playback begins only when you press Play. Captions stay visible. The source clips are silent; Hear caption uses an installed offline voice when available.",15));add(button("Film credits",this::credits));}
 void startStory(boolean resume){persist();stopVideo();state=resume?CinematicState.restore(prefs().getString("moon-0","")):new CinematicState();openScene(false);}
 private void credits(){base("Film credits");add(text("Moon expedition",22));add(text("Visual media: NASA’s Scientific Visualization Studio. Tour of the Moon 4K Redux (2018), title-free visualization using lunar data. Visualization: Ernie Wright; production/editing: David Ladd. Little Makers selected short excerpts, resized/transcoded them and wrote the interactive learning script. This is a scientific visualization, not live camera footage.",17));add(text("The bundled clips contain no source soundtrack, NASA logo or identifiable person. NASA and its contributors do not endorse Little Makers. No source material was used to train a model. Materials used on the 3D workbenches are separately generated texture artwork, not NASA imagery.",15));add(button("Back to films",this::library));}
 void openScene(boolean userRequestedStart){if(state==null)return;persist();base(state.scene().title);failed=false;renderedFirstFrame=false;pendingStart=userRequestedStart;final int current=token;CinematicState.Scene scene=state.scene();add(text("Scene "+(state.node==0?1:state.node==3?3:2)+" of 3 · Moon expedition",13));FrameLayout frame=new FrameLayout(this);frame.setBackgroundColor(Color.BLACK);int height=Math.max(180,Math.min(360,(int)(getResources().getConfiguration().screenWidthDp*.5625f)));add(frame);frame.setLayoutParams(new LinearLayout.LayoutParams(-1,dp(height)));video=new VideoView(this);video.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);if(Build.VERSION.SDK_INT>=26)video.setAudioFocusRequest(0);frame.addView(video,new FrameLayout.LayoutParams(-1,-1,Gravity.CENTER));poster=new ImageView(this);int image=CinematicResources.poster(scene.clip);poster.setImageResource(image);poster.setScaleType(ImageView.ScaleType.FIT_CENTER);poster.setContentDescription("Poster for "+scene.title);frame.addView(poster,new FrameLayout.LayoutParams(-1,-1));caption=text(scene.caption,18);caption.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);add(caption);status=text(state.watched?"Scene watched. Make your choice below.":"Preparing the offline film…",14);add(status);LinearLayout controls=new LinearLayout(this);controls.setBaselineAligned(false);play=button("Play",this::togglePlayback);controls.addView(play,new LinearLayout.LayoutParams(0,-2,1));Button hear=button("Hear caption",()->{if(narrator.muted())status.setText("Sound is off. The caption is ready to read.");else narrator.speak(state.scene().caption+(state.watched?" "+state.scene().question:""));});controls.addView(hear,new LinearLayout.LayoutParams(0,-2,1));add(controls);choices=new LinearLayout(this);choices.setOrientation(1);add(choices);refreshChoices();final VideoView currentVideo=video;
  video.setOnPreparedListener(mp->{if(current!=token||currentVideo!=video)return;ready=true;mp.setVolume(0,0);mp.setLooping(false);mp.setOnInfoListener((m,what,extra)->{if(current==token&&what==MediaPlayer.MEDIA_INFO_VIDEO_RENDERING_START){renderedFirstFrame=true;poster.setVisibility(View.GONE);}return false;});if(state.positionMs>0&&!state.watched)video.seekTo(Math.min(state.positionMs,Math.max(0,video.getDuration()-250)));status.setText(state.watched?"Scene watched. Replay or choose below.":"Ready. Press Play to explore.");if(pendingStart&&active)startPlayback();});
  video.setOnCompletionListener(mp->{if(current!=token||currentVideo!=video)return;clipCompletions++;state.completeClip();persist();play.setText("Replay scene");status.setText(state.finished?"Expedition complete. Your discovery is saved.":"Scene watched. Choose what happens next.");if(state.canReward()&&wallet.creativeCompletion("cinema-0")){sound.win();status.setText("Discovery saved · 1 star and 5 coins. Replay freely.");}refreshChoices();});
  video.setOnErrorListener((mp,what,extra)->{if(current!=token)return true;failed=true;ready=false;pendingStart=false;poster.setVisibility(View.VISIBLE);play.setText("Try film again");status.setText("This film could not play on this device. Try again or return to the film shelf. Progress is kept.");return true;});
  int resource=CinematicResources.video(scene.clip);if(resource==0){failed=true;status.setText("This film is not included in this build.");play.setEnabled(false);}else video.setVideoURI(Uri.parse("android.resource://"+getPackageName()+"/"+resource));if(active)handler.post(tick);
 }
 private void startPlayback(){if(!active||video==null||!ready||failed)return;pendingStart=false;narrator.stop();video.start();play.setText("Pause");handler.removeCallbacks(tick);handler.post(tick);}
 void togglePlayback(){if(state==null)return;if(failed){openScene(true);return;}if(!ready){pendingStart=true;status.setText("Getting the film ready. You can go back at any time.");return;}if(video.isPlaying()){video.pause();state.positionMs=state.watched?0:video.getCurrentPosition();play.setText("Continue");status.setText("Paused. Press Continue when you are ready.");persist();}else{if(state.watched)video.seekTo(0);startPlayback();}}
 private void refreshChoices(){choices.removeAllViews();if(state==null)return;if(!state.watched){choices.addView(text("Watch this short scene to unlock the next choice.",15));return;}if(state.finished){if(wallet.creativeCompletion("cinema-0")){sound.win();status.setText("Discovery saved · 1 star and 5 coins.");}Button again=button("Explore the other path",()->startStory(false));choices.addView(again);choices.addView(button("Back to films",this::library));return;}choices.addView(text(state.scene().question,19));for(int i=0;i<state.scene().choices.length;i++){final int choice=i;Button b=button(state.scene().choices[i],()->choose(choice));if(state.node==0){int image=CinematicResources.poster(CinematicState.SCENES[state.scene().next[i]].clip);android.graphics.drawable.Drawable preview=getDrawable(image);preview.setBounds(0,0,dp(96),dp(54));b.setCompoundDrawables(preview,null,null,null);b.setCompoundDrawablePadding(dp(8));b.setMinHeight(dp(80));}LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(4),0,dp(4));choices.addView(b,p);}}
 void choose(int choice){if(state==null)return;if(!state.choose(choice)){if(state.watched){status.setText(state.node==1?"Look at the curved crater rim. Try the round shape.":"The bright slopes face the Sun. Try another idea.");narrator.speak(status.getText().toString());}return;}stopVideo();persist();openScene(false);}
 private void persist(){if(state!=null){if(video!=null&&ready&&!state.watched)state.positionMs=Math.max(0,video.getCurrentPosition());prefs().edit().putString("moon-0",state.save()).apply();}}
 private void back(){if(state!=null)library();else finish();}
 @Override public void onBackPressed(){back();}
 @Override protected void onSaveInstanceState(Bundle b){persist();b.putBoolean("in_film",state!=null);if(state!=null)b.putString("film_state",state.save());super.onSaveInstanceState(b);}
 @Override protected void onPause(){active=false;pendingStart=false;handler.removeCallbacks(tick);persist();if(video!=null&&video.isPlaying())video.pause();if(play!=null)play.setText("Continue");narrator.stop();sound.stop();super.onPause();}
 @Override protected void onResume(){super.onResume();active=true;long generation=getSharedPreferences("family",0).getLong("quest_reset_generation",0);if(generation!=resetGeneration){resetGeneration=generation;state=null;library();}else if(theme!=null&&theme.dark!=new ThemeManager(this).dark){if(state==null)library();else openScene(false);}}
 @Override protected void onDestroy(){active=false;stopVideo();narrator.close();sound.stop();if(db!=null)db.close();super.onDestroy();}
}
